const feature = (title, intro, body, number) => `<section class="proposal-feature${number ? ' numbered-subsection' : ''}"><h3>${number ? `${number} ` : ''}${title}</h3>${intro ? `<p class="feature-intro">${intro}</p>` : ''}${body.replaceAll('<h3>', '<h4>').replaceAll('</h3>', '</h4>')}</section>`;
const detail = (title, body, number) => `<section class="feature-detail${number ? ' numbered-subsection' : ''}"><h3>${number ? `${number} ` : ''}${title}</h3>${body}</section>`;
const list = items => `<ul class="plain-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const table = (headers, rows) => `<div class="feature-table-wrap"><table class="feature-table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((x,i)=>i===0?`<th scope="row">${x}</th>`:`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const demo = (id,label='MathConcept workflows') => `<div class="demo-wrap"><div class="demo-caption">Interactive demo: ${label}</div><div class="demo" data-demo="${id}" id="demo-${id}"></div></div>`;

export const materialSecurity = {
 title: 'Curriculum access and printing',
 heading: 'Curriculum access and printing',
 intro: 'HQ retains the master collection and approves materials before centres and teachers use them. Permissions follow each user’s role, centre and authorised curriculum. Distribution and printing records help HQ review use of the materials.',
 body:
  detail('Curriculum access',`<p>Users receive approved materials according to their role, centre and authorised curriculum. Originals, student work and answers are managed separately. HQ decides what may be published and who may access it.</p>`)+
  detail('Authorised printing and reprints',`<p>Authorised staff can request printing within the system to centre-approved equipment, without first downloading the source worksheet to a personal computer. Centres set permitted materials and print volumes, selecting the output format that suits the teaching approach.</p><p>Records retain the material version, recipient, copy count, time and whether printing completed, failed or needs follow-up. Reprints remain linked to the original assignment, with the relationship between original and replacement sheets recorded for review and handover. During the pilot, agree printing equipment, arrangements and usage policies together, and name the staff responsible for exceptions.</p>`)+
  detail('Tracing the source of a copy',`<p>Combine worksheet editions, issuing centres, user accounts and printing records to help trace a copy’s source. Staff can review unusual activity alongside related records and follow an agreed investigation procedure.</p>`)+
  detail('Ending access',`<p>End further material access when an account or centre is disabled, or a franchise relationship ends, retaining past usage records for review and handover. Access and printing controls work alongside centre procedures for storing and collecting paper copies to reduce casual bulk access.</p>`)
};

export const chapters = [
 {id:'vision',title:'Proposal overview'},

 {id:'student',title:'Student learning experience',heading:'Write directly on a tablet',intro:'The centre prepares tablets for students to sign in and open their own digital binder when they arrive, with attendance recorded at the same time. Students use a portrait tablet and stylus to write answers and working steps directly on the worksheet.',body:
  demo('student','Student binder and worksheet working')+
  detail('A familiar binder on screen',`<p>The digital binder retains the familiar past, current and future sections. Students open the work available to them, move between worksheet pages and return to saved work from their account.</p>`)+
  detail('Writing space and saved handwriting',`<p>The worksheet keeps the questions and working space together. Saved handwriting remains aligned with the original questions when the student reopens the worksheet, so they can continue from where they stopped.</p>`)},

 {id:'teacher',title:'Teacher assignment and feedback',heading:'Teacher assignment and feedback',intro:'Teachers continue using the familiar progress chart. Materials are stored in the controlled internal library, where teachers choose a class, student and approved worksheets without first finding or saving source files on a personal computer. The system sends assignments to the student’s tablet or arranges authorised printing of compatible paper worksheets, retaining the student, material version and assignment record.',body:
  demo('teacher','Class selection, progress and assignment')+
  detail('Assignment, marking and corrections',`<p>Teachers decide when future work becomes available and review saved tablet answers or successfully synchronised smartpen work in the student’s learning record. When needed, photographs or scans can also bring paper answers into the record. Teachers add marking and comments, assign corrections and confirm completion, keeping original answers and later corrections together. Reprinted worksheets remain linked to the original assignment.</p>`)+
  detail('Learning records and the working process',list([
   '<strong>Answers and order of working:</strong> retain handwritten numbers, equations, diagrams and working steps. Where the device records stroke order and timing, teachers can follow work as it arrives, replay the sequence and review mapped questions.',
   '<strong>Writing time, speed and pauses:</strong> use available timing records to estimate active writing time, changes in speed, where writing stopped, the length of a gap and where it resumed. Active writing and pauses are shown separately, so a pause becomes a point for discussion rather than a judgement about the student.',
   '<strong>Rewritten work and corrections:</strong> retain recorded new strokes when a pupil returns to an earlier area, tries again or makes corrections, alongside teacher marking. Physical erasing on paper is not assumed to remove previously captured strokes.',
   '<strong>Progress and results:</strong> track assigned, submitted, awaiting marking, awaiting correction and completed work, with saved or pending-sync status and teacher-confirmed results. Only saved or successfully synchronised work selected by the teacher is released to parents.',
   '<strong>Writing pressure:</strong> where the selected device supports it, pressure changes can provide a reference for handwriting practice and teacher observation.'
  ]))+
  detail('AI-assisted learning analysis',list([
   '<strong>Check answers and working:</strong> recognise recorded answers, suggest checks against approved answers and highlight potentially incorrect steps. Automatic marking applies only to validated question types; teachers judge handwritten reasoning and solution methods.',
   '<strong>Identify recurring errors and revision topics:</strong> review several assignments for patterns such as carrying, place value or operation order, helping teachers choose topics to revisit.',
   '<strong>Highlight steps worth discussing:</strong> combine available pause, rewriting and answer records to suggest steps that may benefit from explanation, with the relevant work attached for review.',
   '<strong>Review individual progress:</strong> compare the same pupil’s accuracy, order of working, corrections and available timing on similar questions, summarising improvement and areas for practice without judging performance by speed alone.',
   '<strong>Suggest personalised practice and hints:</strong> recommend approved questions or draft targeted exercises, hints and explanations for teachers to check and assign.',
   '<strong>Prepare lesson and parent summaries:</strong> turn confirmed observations into progress and follow-up suggestions for teachers to edit and publish. De-identified class patterns can also inform materials and lesson planning.'
  ])+`<p>Each AI suggestion includes its supporting answer or handwriting record. Items needing review are brought together so teachers can combine the evidence with classroom observations and decide on explanations, corrections and practice.</p>`)+
  detail('Lesson reports and parent follow-up',`<p>Teachers can draft a report in the lesson records, recording the lesson date, instructor and learning focus, with A–E ratings for arriving on time, submitting all homework, working diligently in class and independent study, and notes for the parent. Only published reports appear in the parent handbook; drafts remain unavailable to parents. Parents can acknowledge that they have read a report or reply, and the teacher can review and follow up within that report.</p>`)+
  detail('Awarding student stamps',`<p>Teachers can award a stamp for a student’s learning effort or progress and record the reason. Students view their own stamps and encouragement reasons on a separate collection page, keeping the worksheet writing area clear. Centre information, notices and lesson reports are kept in the parent app’s digital handbook.</p>`)},

 {id:'library',title:'Material management and authoring',heading:'Material management and authoring',intro:'The material library brings together a catalogue, reusable question bank, AI-assisted creation, approval, access permissions and controlled printing. Teachers select content for tablet assignment or compatible printed worksheets to suit the lesson.',body:
 feature('Existing material digitisation', 'We recommend organising existing materials in stages. First build the catalogue and retain the content and layouts of original worksheets for tablet assignment or printed use; then gradually organise questions into reusable, editable content. This allows a pilot with selected materials before expanding the library.',
  detail('Preparing and converting the existing library',table(['Stage','Usable result','Review and acceptance'],[
   ['1. Catalogue the collection','Build the catalogue using the existing grades, topics, collections and worksheet numbers, so teachers can find what they need.','Check the classifications, file completeness, duplicate content and which version to use.'],
   ['2. Retain original worksheets for teaching','Preserve approved worksheet layouts for tablet assignment or compatible printed copies, supporting student handwriting and teacher marking.','Check layout, page count, writing positions and printed output to preserve the original teaching use; editable content is prepared in a later stage.'],
   ['3. Prepare reusable questions','Organise verified questions, diagrams and answers as individual items that can later be combined into worksheets.','Choose the grades and collections to prioritise, retaining each question’s source and version.'],
   ['4. Create editable content','Convert text, equations, diagrams and answers into editable content, ready for future authoring and revisions after checking.','Review text, equations and diagrams individually to confirm which content is ready for editing and reuse.']
  ]))+
  detail('Quality checks and migration acceptance',list([
   'Check decimal points, fractions, units, diagrams, question parts and the links between questions and answers, so the converted content is suitable for teaching.',
   'Retain the original materials and revision history, distinguishing duplicate files from different versions. The report will list usable materials, verified questions and outstanding items.',
   'Keep material needing further checks in its original page form, with designated reviewers approving it before it enters the editable question bank.',
   'Report usable materials and verified editable questions separately, making it easier to plan further conversion and authoring.'
  ])))+
 feature('New material creation and approval', '',
detail('Creating and approving new materials',`<p>Build a material-editing platform similar to Wix or Canva, where teachers can create and edit worksheets and interactive exercises by dragging and dropping. The platform can gradually add mathematical-symbol entry and formula editing with tools such as MathType. AI can also generate content, layouts, Python code or custom HTML interactive components for teachers to check and adjust. This gives teachers more freedom to design layouts and turn the same material into online interactive exercises or games, while retaining printing. Where needed, materials can also be exported as PDF or Word documents to fit existing workflows. AI can help generate questions, hints, solutions and interactive content for teachers to review and edit. Before publication, preview tablet and printed layouts to check questions, diagrams and working space, so the content is ready for teaching use.</p>`)+
  detail('Keeping traditional-format materials',`<p>Existing materials such as PDFs can also be stored in the controlled library and managed alongside new content, with viewing, assignment and printing governed by permissions. Normal teaching accounts do not provide original-file downloads. Originals, answers and student work are managed separately; access and printing must stay within the user’s authorisation.</p>`)+
  detail('Editorial responsibilities and answer access',list([
   'MathConcept names the authors, mathematical reviewers and staff authorised to approve publication.',
   'Student materials, search results and exports must not expose restricted answers or teacher notes.',
   'MathConcept designates who can approve material processing and manages external services and AI use according to agreed purposes, usage rights and confidentiality requirements.'
  ])))},
 {id:'system',title:'Centre management',heading:'Centre management',intro:'',body:
 feature('Centre administration and scheduling', 'The centre can manage enrolment, class arrangements, parent communication and fees in one system, reducing repeated checks between different spreadsheets and records.',
 demo('operations','Leave, timetable changes and make-up lessons')+
 detail('Interactive timetable and lesson changes',`<p>Staff can adjust lessons by dragging them or using keyboard controls. One-off and regular timetable changes can have an effective date; temporary changes can also have an end date. Before confirmation, the system checks teacher availability, class capacity and time clashes, and lists the affected lessons and changes in lesson counts.</p>`)+
 detail('Leave and make-up follow-up',`<p>Parents can submit leave requests and make-up preferences. The system distinguishes requests awaiting follow-up from confirmed arrangements. Once staff and the parent agree a time, staff can move the student to the make-up slot on the timetable.</p>`)+
 detail('Fees and lesson counts',`<p>The system shows any increase or reduction in lessons after a timetable change, so staff can decide whether to approve extra lessons or retain make-up credits, and follow up the related invoices and receipts.</p>`)+
 detail('Student and communication records',`<p>Each student’s lessons, leave, receipts, reasons for changes and parent communications are kept together for staff to review and hand over.</p>`), '5.1')+
 feature('Billing and bank reconciliation', 'We recommend using AI to help with the flow from invoice → parent payment proof → checks and approval → receipt → bank reconciliation. The centre can choose staff approval or automatic approval and receipt issuance when all required checks pass. Mismatched or uncertain cases always go to staff for follow-up.',
 demo('billing','Payment review, receipts and final audit')+
 detail('Assessment and first-enrolment invoices',`<p>Booking a paid assessment creates an invoice showing the assessment date, amount and payment deadline. The first-enrolment invoice is issued after staff review the application. Approval of the verified first payment also activates the student’s enrolment record.</p>`)+
 detail('Two-month tuition',`<p>The fee is HK$2,000 for a nominal eight-lesson package valid for two calendar months. Students can have different periods, such as September–October or October–November. The existing weekly timetable and calendar dates may naturally produce seven, eight or nine lessons in a period. The fee remains the same, with no additional charge or refund. The teaching schedule averages 48 weeks annually.</p>`)+
 detail('Lesson counts after a regular timetable change',`<p>If a regular timetable change increases the period from x to x+1 lessons, the centre chooses whether to approve the extra lesson at the original fee or exclude it. If the count falls from x to x−1, the centre chooses whether to grant make-up credit. These decisions concern changes caused by rescheduling and are separate from the seven, eight or nine lessons that naturally fall within the original timetable.</p>`)+
 detail('Invoice issue dates and payment deadlines',`<p>The next period’s invoice is issued automatically on the 20th of the preceding month, with payment due on the following month’s 20th. For example, October–November tuition is invoiced on 20 September and due on 20 October. Approval of a renewal payment also issues a receipt, but does not activate enrolment again.</p>`)+
 detail('Lesson dates on invoices and receipts',`<p>Tuition invoices and receipts list each actual lesson date within the billing period so parents and staff can check the arrangements. An approved timetable change updates the relevant documents to the confirmed dates while retaining the original records.</p>`)+
 detail('Parent payments',`<p>Parents can view the amount due and payment deadline, and copy the FPS payment details. After payment, they upload proof for checking and approval under the centre’s selected policy before a receipt is issued.</p>`)+
 detail('Invoice queues',`<p>The three tabs are 待家長付款 (waiting for parent payment), 待中心核對 (waiting for centre review) and 已發收據 (receipt issued). The default is 待中心核對, with the oldest payment proofs first. Unpaid invoices show deadlines and overdue notices; issued receipts appear newest first. Each row is one invoice, so a student can have unpaid, awaiting-review and completed invoices at the same time.</p>`)+
 detail('Search and filters',`<p>Search by student name, student number or invoice number, and filter by charge type or billing month, with around 25 invoices per page. The month filter can remain empty so older unpaid invoices stay visible.</p>`)+
 detail('AI payment-proof checks',`<p>The proposed AI checks read the payment date and time, payer name, amount, payment method, transaction reference, and receiving account and name from the proof, then compare them with the invoice and the centre’s authorised receiving details. The system also checks for duplicate proof or transactions. Amount or recipient mismatches, incomplete details and uncertain results are flagged with reasons for staff follow-up.</p>`)+
 detail('Centre-selectable approval modes',`<p>The centre can choose AI checks followed by staff approval, or automatic approval after all checks pass. In the first mode, AI prepares the results for staff to confirm and issue the receipt. In the second, the system approves and issues a receipt only when invoice, payment and recipient details satisfy every required centre check, with no duplicate or uncertain result. Both modes send mismatches, duplicates, incomplete details and uncertain cases to staff.</p>`)+
 detail('Payment-proof review',`<p>Open the review popup from the list, with the invoice on the left and payment proof on the right; the documents stack vertically on phones. Each document can be scrolled and zoomed independently. The current list and filters remain in place, with no need to move to another page.</p>`)+
 detail('Approval and proof resubmission',`<p>For a case requiring staff review, select 確認並發出收據 (confirm and issue receipt) to approve the payment and issue its receipt in one action. Success closes the popup, refreshes the current filtered list, briefly shows confirmation and moves the invoice to 已發收據. If proof needs to be supplied or corrected, staff must give a reason for returning it and clearly request replacement evidence, so parents do not mistake it for a request to pay again.</p>`)+
 detail('Saving and recovery',`<p>Staff cannot close the review popup or leave the page while saving. If saving fails or the result is uncertain, the popup and entered contents remain available for staff to continue. Before retrying, check whether the receipt has already been issued to avoid duplicates.</p>`)+
 detail('Reminders and archive',`<p>Show when the last reminder was sent and prevent another within 24 hours. Cancelled and void invoices are archived separately, with reminder and cancellation records retained for staff review.</p>`)+
 detail('Receipt amendments after timetable changes',`<p>An approved timetable change updates the actual lesson dates on the invoice. If a receipt has already been issued, an amended version lists each confirmed lesson date. The amendment retains the original payment date, receipt date and paid amount, and separately records the actual amendment date and reason. The original and all previous receipt versions remain available for review.</p>`)+
 detail('Final reconciliation',`<p>After a bank statement is uploaded, the proposed AI matching uses payer or account names, transaction references, amounts and dates to help match bank credits with invoices and receipts. It highlights missing credits, extra payments, duplicate transactions and uncertain matches. The system prevents double-counting transactions or allocating the same credit more than once. Staff follow up unexplained differences.</p>`)+
 detail('Dates and reconciliation records',`<p>Record the parent’s payment date, proof submission date, receipt issue date and bank posting date separately to handle payments spanning different days or month-end. Staff see receipt issuance and verified bank credits as separate stages. Final reconciliation confirms credits against bank records and brings pending or mismatched items together for follow-up.</p>`)+
 detail('Other payment arrangements',`<p>Cash, cheques, combined payments, partial payments and refunds follow their respective workflows, with rules to be agreed separately. Bank statements are the basis for reconciliation. A direct bank connection is optional and requires bank confirmation before separate assessment.</p>`)+
 detail('Configure the centre’s payment rules',`<p>We would work with the centre to configure receiving accounts and names, required payment checks and automatic approval conditions. Matching and payment-allocation rules would follow the bank records the centre uses, keeping daily checks aligned with its billing arrangements.</p>`), '5.2')},
 {id:'parent',title:'Parent app',heading:'Parent app',intro:'Parents can use a phone app to view their children’s lessons, learning records and payments, and communicate directly with the centre. One account can switch between children, keeping each child’s timetable, homework and invoices together and reducing the need to search old messages or ask the centre for updates.',body:
 demo('parent','Parent home, digital handbook, payments and messages')+
 detail('Home and child switching',`<p>The home screen lists all upcoming scheduled lessons for the selected child, including dates, times, teachers and make-up arrangements. Parents can switch children or open class reports and homework directly. The 調堂 (lesson changes) shortcut opens a popup on the home screen where parents select a lesson to request leave or provide make-up preferences. Centre staff follow up the preferences, confirm the replacement slot and update the timetable.</p>`, '6.1')+
 detail('Attendance at the centre',`<p>Parents can open their child’s attendance QR code in the app for centre staff to scan on arrival. The attendance record is linked to that day’s lesson and can be reviewed by the parent and centre.</p>`, '6.2')+
 detail('Leave and make-up lessons',`<p>Parents can submit leave against a specific lesson and view leave records and make-up lessons awaiting arrangement. They can suggest dates and add notes for the centre. Once the centre confirms the arrangement, parents attend at the new time and the lesson appears in the child’s timetable.</p>`, '6.3')+
 detail('Digital handbook: lesson reports',`<p>The paper handbook’s main functions are brought into the parent app, with Lesson reports, Centre calendar and Centre information tabs. Each lesson report records the date, instructor and learning focus, A–E ratings for arriving on time, submitting all homework, working diligently in class and independent study, and notes for the parent. Parents see only published reports and can acknowledge reading or leave a reply, with the conversation kept alongside the report.</p>`, '6.4')+
 detail('Digital handbook: centre calendar and information',`<p>Parents can check the centre calendar, contact details and parent information, including severe-weather arrangements and other notices published by the centre. The centre calendar is shown separately from the child’s timetable so general centre arrangements are distinct from individual lessons.</p>`, '6.5')+
 detail('Homework and corrections',`<p>Parents can view marked work and released homework to follow their child’s learning and corrections. Teachers continue to control when future worksheets are released; parents cannot open material that has not yet been assigned.</p>`, '6.6')+
 detail('Payment notices and proof',`<p>Each invoice shows the charge, amount, deadline and relevant lesson dates. Parents can copy the FPS receiving details, make payment, then upload proof and enter the payer name and payment date. The app shows the invoice’s progress so parents do not need to send a separate message for an update.</p>`, '6.7')+
 detail('Review results and electronic receipts',`<p>The centre can choose AI checks followed by staff approval, or automatic approval and receipt issuance when every required check passes. Mismatched, duplicate or uncertain cases go to staff. Parents can view issued receipts and individual lesson dates in the app. If replacement proof is needed, the reason is shown with a clear reminder that a parent who has already paid does not need to pay again. Amended receipts and previous versions remain available after timetable changes.</p>`, '6.8')+
 detail('Centre messages and notifications',`<p>Parents can message the centre directly and retain conversations about lessons, leave and payments. The app can also provide notifications for timetable changes, payment reminders, proof follow-up and receipt issuance, keeping centre-related tasks in one place.</p>`, '6.9')},
 {id:'franchise',title:'Multi-centre management',heading:'Multi-centre management',intro:'HQ centrally manages material publication, each centre’s curriculum access and operating policies. Each centre handles teaching, parent communication and fees within its authorised scope. New centres can use the same workflow while keeping their student and operational records separate.',body:
  demo('franchise','Tsuen Wan and Hang Hau')+
  table(['Feature','Included function','Condition or responsibility'],[
   ['Centre and role permissions','Set permitted curricula and access to student and operational records by centre and responsibility.','Records remain within the user’s authorised scope when switching between centre views.'],
   ['Material publication and versions','HQ reviews, publishes and manages material versions, and sets each centre’s curriculum access.','Centres can use only the materials they are authorised to access.'],
   ['Operational reporting and review','Centres view outstanding class and payment work. HQ views agreed reports across centres and unusual access or printing records.','Use jointly agreed reporting scopes and calculations, with designated staff reviewing unusual activity alongside related records.'],
   ['New centres and staff changes','Support new centre openings, staff transfers and departures, and changes to access, support and handover when a franchise relationship ends.','Confirm interface languages, responsible staff, and the timing and procedure for ending access.']
  ])+detail('Shared management and data handover',list([
   'Centres use the same workflows while managing their own centre details, teachers and daily records. HQ brings permissions and cross-centre reporting together to compare operations and arrange support.',
   'MathConcept retains ownership of its supplied curriculum and operational data. We would agree usage rights, data exports and handover arrangements together to support continued operation.'
  ]))},


];

export function chapterHTML(c,i){return `<section class="chapter" id="${c.id}" data-chapter="${i}" aria-labelledby="heading-${c.id}"><div class="chapter-heading"><h2 id="heading-${c.id}">${i+1}. ${c.heading}</h2>${c.intro ? `<p class="section-intro">${c.intro}</p>` : ''}</div>${c.body}</section>`}
